-- Milestone 4: tracking & attribution
ALTER TABLE "Store" ADD COLUMN "trackingKey" TEXT;
CREATE UNIQUE INDEX "Store_trackingKey_key" ON "Store"("trackingKey");
CREATE TYPE "AttributionModel" AS ENUM ('FIRST_TOUCH','LAST_TOUCH','LAST_NON_DIRECT','LINEAR');
CREATE TABLE "Visitor" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "anonymousId" TEXT NOT NULL, "firstSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lastSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Visitor_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Visitor_organizationId_anonymousId_key" ON "Visitor"("organizationId","anonymousId");
CREATE INDEX "Visitor_organizationId_lastSeenAt_idx" ON "Visitor"("organizationId","lastSeenAt");
CREATE TABLE "TrackingSession" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "visitorId" TEXT NOT NULL, "sessionKey" TEXT NOT NULL, "landingPage" TEXT, "referrer" TEXT, "utmSource" TEXT, "utmMedium" TEXT, "utmCampaign" TEXT, "utmContent" TEXT, "utmTerm" TEXT, "fbclid" TEXT, "gclid" TEXT, "ttclid" TEXT, "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lastActivityAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "TrackingSession_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "TrackingSession_organizationId_sessionKey_key" ON "TrackingSession"("organizationId","sessionKey");
CREATE INDEX "TrackingSession_visitorId_idx" ON "TrackingSession"("visitorId");
CREATE TABLE "Touchpoint" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "visitorId" TEXT NOT NULL, "sessionId" TEXT, "source" TEXT NOT NULL DEFAULT 'direct', "medium" TEXT, "campaign" TEXT, "content" TEXT, "term" TEXT, "clickIdType" TEXT, "clickId" TEXT, "landingPage" TEXT, "referrer" TEXT, "isDirect" BOOLEAN NOT NULL DEFAULT true, "occurredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Touchpoint_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Touchpoint_sessionId_key" ON "Touchpoint"("sessionId");
CREATE INDEX "Touchpoint_organizationId_visitorId_occurredAt_idx" ON "Touchpoint"("organizationId","visitorId","occurredAt");
CREATE INDEX "Touchpoint_organizationId_source_campaign_idx" ON "Touchpoint"("organizationId","source","campaign");
CREATE TABLE "TrackingEvent" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "storeId" TEXT, "visitorId" TEXT, "sessionKey" TEXT, "clientEventId" TEXT NOT NULL, "type" TEXT NOT NULL, "url" TEXT, "referrer" TEXT, "properties" JSONB, "orderExternalId" TEXT, "orderId" TEXT, "valueMinor" BIGINT, "currency" TEXT, "occurredAt" TIMESTAMP(3) NOT NULL, "receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "TrackingEvent_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "TrackingEvent_organizationId_clientEventId_key" ON "TrackingEvent"("organizationId","clientEventId");
CREATE INDEX "TrackingEvent_organizationId_type_occurredAt_idx" ON "TrackingEvent"("organizationId","type","occurredAt");
CREATE INDEX "TrackingEvent_organizationId_orderExternalId_idx" ON "TrackingEvent"("organizationId","orderExternalId");
CREATE TABLE "AttributionCredit" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "orderId" TEXT NOT NULL, "model" "AttributionModel" NOT NULL, "touchpointId" TEXT, "revenueMinor" BIGINT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AttributionCredit_pkey" PRIMARY KEY ("id"));
CREATE INDEX "AttributionCredit_organizationId_model_idx" ON "AttributionCredit"("organizationId","model");
CREATE INDEX "AttributionCredit_orderId_model_idx" ON "AttributionCredit"("orderId","model");
CREATE INDEX "AttributionCredit_touchpointId_idx" ON "AttributionCredit"("touchpointId");
ALTER TABLE "Visitor" ADD CONSTRAINT "Visitor_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "TrackingSession" ADD CONSTRAINT "TrackingSession_visitorId_fkey" FOREIGN KEY ("visitorId") REFERENCES "Visitor"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Touchpoint" ADD CONSTRAINT "Touchpoint_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Touchpoint" ADD CONSTRAINT "Touchpoint_visitorId_fkey" FOREIGN KEY ("visitorId") REFERENCES "Visitor"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Touchpoint" ADD CONSTRAINT "Touchpoint_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "TrackingSession"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "TrackingEvent" ADD CONSTRAINT "TrackingEvent_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "TrackingEvent" ADD CONSTRAINT "TrackingEvent_visitorId_fkey" FOREIGN KEY ("visitorId") REFERENCES "Visitor"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "AttributionCredit" ADD CONSTRAINT "AttributionCredit_touchpointId_fkey" FOREIGN KEY ("touchpointId") REFERENCES "Touchpoint"("id") ON DELETE SET NULL ON UPDATE CASCADE;
